import {readFileSync,writeFileSync} from 'node:fs';
import {randomUUID} from 'node:crypto';
import {pathToFileURL} from 'node:url';
import assert from 'node:assert/strict';
const {buildApp}=await import(pathToFileURL(process.env.MOTE_CONNECTORS_PROCESS_ENTRY).href);
const root=process.env.GENERATED_CONNECTOR_ROOT,phase=process.env.GENERATED_CONNECTOR_PHASE,password='Generated-connector-process-password-01';
const transports={google:({userId})=>({oauthFactory:()=>{const oauth={credentials:{},generateCodeVerifierAsync:async()=>({codeVerifier:'generated-verifier',codeChallenge:'generated-challenge'}),generateAuthUrl:value=>'https://generated.invalid/oauth?'+new URLSearchParams({state:value.state}),getToken:async()=>({tokens:{access_token:'generated-'+userId,refresh_token:'generated-refresh-'+userId,scope:'https://www.googleapis.com/auth/gmail.readonly'}}),setCredentials:value=>{oauth.credentials=value;},getAccessToken:async()=>({token:oauth.credentials.access_token})};return oauth;},fetch:async url=>{const path=new URL(String(url)).pathname;let value;if(path.endsWith('/profile'))value={emailAddress:'same-account@synthetic.invalid',historyId:'100'};else if(path.endsWith('/messages'))value={messages:[{id:'same-message'}]};else if(path.endsWith('/messages/same-message'))value={id:'same-message',payload:{mimeType:'text/plain',body:{data:Buffer.from('PROCESS_PRIVATE_'+userId).toString('base64url')}}};else if(path.endsWith('/history'))value={history:[],historyId:'101'};else throw Error('External network forbidden');return new Response(JSON.stringify(value));}})};
const node=await buildApp({dataDir:root},{connectorTransports:transports});
try{
 if(phase==='first')await node.accounts.initialize('generated-admin',password);
 const address=await node.app.listen({host:'127.0.0.1',port:0}),headers={'x-mote-protocol-version':'2','x-mote-ingress-version':'3'},raw=(token,path,method='GET',payload)=>fetch(address+path,{method,headers:{...headers,...(token?{authorization:'Bearer '+token}:{}),...(payload?{'content-type':'application/json'}:{})},...(payload?{body:JSON.stringify(payload)}:{})}),request=async(...args)=>{const r=await raw(...args),value=await r.json();assert.equal(r.status,200,JSON.stringify(value));return value;},login=username=>request(undefined,'/api/auth/login','POST',{username,password,mode:'client',durationMs:86400000}),wait=async(token,id)=>{for(let i=0;i<1000;i++){const task=await request(token,'/api/tasks/'+id);if(task.state==='succeeded')return task;if(['stale','blocked','failed','cancelled'].includes(task.state))throw Error(JSON.stringify(task));await new Promise(resolve=>setTimeout(resolve,5));}throw Error('Generated task timed out');};
 let saved;
 if(phase==='first'){
  const admin=await login('generated-admin');for(const username of ['generated-a','generated-b'])await request(admin.token,'/api/admin/accounts','POST',{username,password});const a=await login('generated-a'),b=await login('generated-b'),catalog=await request(admin.token,'/api/admin/plugins');await request(admin.token,'/api/admin/connectors/gmail/install','POST',{expectedRevision:catalog.revision,operationId:randomUUID()});
  saved={a,b};for(const [key,token] of [['a',a.token],['b',b.token]]){const view=await request(token,'/api/connectors');await request(token,'/api/connectors/same','PUT',{expectedRevision:view.revision,connection:{provider:'gmail',autoSync:false,googleClientId:'generated',googleClientSecret:'generated-secret',googleRedirectUri:'https://generated.invalid/callback'}});await request(token,'/api/connectors/same/enable','POST',{expectedRevision:(await request(token,'/api/connectors')).revision});const auth=await request(token,'/api/connectors/same/start','POST',{});saved[key].auth={state:new URL(auth.authorizationUrl).searchParams.get('state'),taskId:auth.taskId};}writeFileSync(root+'/generated-receipt.json',JSON.stringify(saved),{mode:0o600});
 }else{
  saved=JSON.parse(readFileSync(root+'/generated-receipt.json','utf8'));
  for(const record of [saved.b,saved.a]){const callback=await raw(undefined,'/oauth/google/callback?'+new URLSearchParams({state:record.auth.state,code:'generated-code'}));assert.equal(callback.status,200);await wait(record.token,record.auth.taskId);}
  for(const record of [saved.a,saved.b]){await wait(record.token,(await request(record.token,'/api/connectors/same/sync','POST',{operationId:'process-sync'})).id);const source=(await request(record.token,'/api/sources')).items[0],original=(await request(record.token,'/api/ingress/sources/'+source.id+'/originals')).items[0];record.original=original.ref;record.ticket=(await request(record.token,'/api/ingress/originals/'+original.ref.slice(9)+'/tickets','POST',{mode:'download'})).ticket;const content=await raw(record.token,'/api/ingress/originals/'+original.ref.slice(9)+'/content?'+new URLSearchParams({ticket:record.ticket}));assert.equal(content.status,200);const message=JSON.parse(await content.text());assert.equal(message.id,'same-message');assert.equal(Buffer.from(message.payload.body.data,'base64url').toString(),'PROCESS_PRIVATE_'+record.userId);}
  const foreign=await raw(saved.b.token,'/api/ingress/originals/'+saved.a.original.slice(9)+'/content?'+new URLSearchParams({ticket:saved.a.ticket}));assert.equal(foreign.status,404);assert.equal((await raw(undefined,'/oauth/google/callback?'+new URLSearchParams({state:saved.a.auth.state,code:'replay'}))).status,400);
 }
 console.log(JSON.stringify({phase,ok:true,users:2}));
}finally{await node.app.close();}
